const data = $input.all();

return data.map(item => {
  const d = item.json;

  return {
    json: {
      operationId: d.operation_id || "N/A",
      operationName: d.operation_name || "Unknown",
      department: d.department || "Unknown",
      owner: d.owner || "Unassigned",
      status: d.status || "Unknown",

      taskCount: Number(d.task_count || 0),
      completedTasks: Number(d.completed_tasks || 0),
      pendingTasks: Number(d.pending_tasks || 0),
      failedTasks: Number(d.failed_tasks || 0),

      deadline: d.deadline || "N/A",
      errorMessage: d.error_message || "",
      uptime: Number(d.uptime || 0),
      customerIssues: Number(d.customer_issues || 0),

      lastUpdated: d.last_updated || ""
    }
  };
});

const output = $json.output;

let data;

try {
  data = typeof output === 'string'
    ? JSON.parse(output)
    : output;
} catch (error) {
  throw new Error('AI output is not valid JSON: ' + error.message);
}

return [
  {
    json: data
  }
];

